[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fresh Pantry — Discover Everyday Deliciousness</title>
<meta name="description" content="A neighborhood grocery store offering unique, high-quality food products at great prices.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --green: #2D6A4F;
  --green-dark: #1B4332;
  --green-light: #40916C;
  --green-muted: #B7E4C7;
  --orange: #F4A261;
  --orange-dark: #E76F51;
  --orange-light: #F4C584;
  --cream: #FEFAE0;
  --cream-dark: #F5F0D0;
  --white: #FFFDF5;
  --text-dark: #1A1A1A;
  --text-body: #3D3D3D;
  --text-muted: #6B7280;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  color: var(--text-body);
  background: var(--cream);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Nunito', sans-serif;
  color: var(--text-dark);
  line-height: 1.2;
}

a { text-decoration: none; color: inherit; }
button { font-family: 'Plus Jakarta Sans', sans-serif; cursor: pointer; border: none; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
input { font-family: 'Plus Jakarta Sans', sans-serif; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== GRAIN OVERLAY ===== */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n' x='0' y='0'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  background-size: 200px;
  opacity: 0.5;
  pointer-events: none;
  z-index: 9999;
}

/* ===== ANIMATIONS ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.92); }
  to { opacity: 1; transform: scale(1); }
}
@keyframes slideInLeft {
  from { opacity: 0; transform: translateX(-30px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== HEADER ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(254, 250, 224, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(45, 106, 79, 0.08);
  transition: var(--transition);
}
.header.scrolled {
  box-shadow: var(--shadow-md);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 24px;
  color: var(--green);
}
.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--green);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 20px;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-links a {
  font-weight: 600;
  font-size: 15px;
  color: var(--text-body);
  transition: var(--transition);
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green);
  border-radius: 2px;
  transition: width 0.3s ease;
}
.nav-links a:hover { color: var(--green); }
.nav-links a:hover::after { width: 100%; }

.mobile-menu-btn {
  display: none;
  background: none;
  width: 40px;
  height: 40px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2.5px;
  background: var(--green-dark);
  border-radius: 2px;
  transition: var(--transition);
}
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--cream);
  border-bottom: 1px solid rgba(45, 106, 79, 0.1);
  box-shadow: var(--shadow-lg);
  padding: 16px 24px;
  z-index: 999;
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block;
  padding: 14px 0;
  font-weight: 600;
  font-size: 16px;
  color: var(--text-body);
  border-bottom: 1px solid rgba(45, 106, 79, 0.06);
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: var(--green); }

/* ===== HERO ===== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding-top: 72px;
  background: linear-gradient(170deg, var(--cream) 0%, #e8f5e9 40%, var(--cream) 70%, #fff8e1 100%);
}
.hero-bg-shapes {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.hero-shape {
  position: absolute;
  border-radius: 50%;
  opacity: 0.12;
}
.hero-shape-1 {
  width: 500px; height: 500px;
  background: var(--green);
  top: -100px; right: -100px;
  animation: float 8s ease-in-out infinite;
}
.hero-shape-2 {
  width: 300px; height: 300px;
  background: var(--orange);
  bottom: -50px; left: -50px;
  animation: float 6s ease-in-out infinite 1s;
}
.hero-shape-3 {
  width: 200px; height: 200px;
  background: var(--green-muted);
  top: 30%; left: 15%;
  animation: float 10s ease-in-out infinite 0.5s;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(45, 106, 79, 0.1);
  border: 1px solid rgba(45, 106, 79, 0.15);
  color: var(--green);
  font-weight: 700;
  font-size: 14px;
  padding: 8px 18px;
  border-radius: 100px;
  margin-bottom: 24px;
  animation: fadeInUp 0.8s ease forwards;
}
.hero-badge-dot {
  width: 8px; height: 8px;
  background: var(--green);
  border-radius: 50%;
  animation: pulse 2s ease infinite;
}
.hero h1 {
  font-size: clamp(40px, 6vw, 68px);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -1.5px;
  color: var(--green-dark);
  margin-bottom: 20px;
  animation: fadeInUp 0.8s ease forwards 0.15s;
  opacity: 0;
}
.hero h1 span {
  background: linear-gradient(135deg, var(--orange) 0%, var(--orange-dark) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--text-muted);
  max-width: 520px;
  line-height: 1.7;
  margin-bottom: 36px;
  animation: fadeInUp 0.8s ease forwards 0.3s;
  opacity: 0;
}
.hero-ctas {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  animation: fadeInUp 0.8s ease forwards 0.45s;
  opacity: 0;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 16px;
  padding: 14px 28px;
  border-radius: var(--radius-md);
  transition: all 0.25s ease;
}
.btn-primary {
  background: var(--green);
  color: white;
  box-shadow: 0 4px 14px rgba(45, 106, 79, 0.3);
}
.btn-primary:hover {
  background: var(--green-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(45, 106, 79, 0.4);
}
.btn-secondary {
  background: white;
  color: var(--green);
  border: 2px solid rgba(45, 106, 79, 0.15);
}
.btn-secondary:hover {
  border-color: var(--green);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.hero-visual {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
}
.hero-image-card {
  width: 420px;
  height: 460px;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, #a8d5ba 0%, #d4e6b5 40%, #f7d794 100%);
  box-shadow: var(--shadow-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  animation: scaleIn 1s ease forwards 0.2s;
  opacity: 0;
}
.hero-image-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(45, 106, 79, 0.1));
}
.hero-emoji-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  font-size: 52px;
  position: relative;
  z-index: 1;
}
.hero-emoji-grid span {
  animation: float 4s ease-in-out infinite;
}
.hero-emoji-grid span:nth-child(2) { animation-delay: 0.3s; }
.hero-emoji-grid span:nth-child(3) { animation-delay: 0.6s; }
.hero-emoji-grid span:nth-child(4) { animation-delay: 0.9s; }
.hero-emoji-grid span:nth-child(5) { animation-delay: 1.2s; }
.hero-emoji-grid span:nth-child(6) { animation-delay: 1.5s; }
.hero-emoji-grid span:nth-child(7) { animation-delay: 1.8s; }
.hero-emoji-grid span:nth-child(8) { animation-delay: 2.1s; }
.hero-emoji-grid span:nth-child(9) { animation-delay: 2.4s; }

.hero-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 60px;
  padding: 80px 0;
}

/* Floating tag on hero image */
.hero-float-tag {
  position: absolute;
  background: white;
  border-radius: var(--radius-md);
  padding: 12px 18px;
  box-shadow: var(--shadow-lg);
  font-weight: 700;
  font-size: 14px;
  color: var(--green-dark);
  display: flex;
  align-items: center;
  gap: 8px;
  z-index: 2;
  animation: float 5s ease-in-out infinite;
}
.hero-float-tag-1 { bottom: 40px; left: -30px; animation-delay: 0.5s; }
.hero-float-tag-2 { top: 30px; right: -30px; animation-delay: 1.5s; }

/* ===== SECTION COMMON ===== */
.section {
  padding: 100px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 56px;
}
.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--green);
  margin-bottom: 14px;
}
.section-title {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 900;
  letter-spacing: -0.5px;
  margin-bottom: 14px;
}
.section-subtitle {
  font-size: 17px;
  color: var(--text-muted);
  max-width: 560px;
  margin: 0 auto;
}

/* ===== FEATURED PRODUCTS CAROUSEL ===== */
.products-section {
  background: var(--white);
  overflow: hidden;
}
.carousel-wrapper {
  position: relative;
  padding: 0 20px;
}
.carousel-track {
  display: flex;
  gap: 24px;
  overflow: hidden;
  scroll-behavior: smooth;
}
.carousel-track-inner {
  display: flex;
  gap: 24px;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.product-card {
  flex-shrink: 0;
  width: 260px;
  background: var(--cream);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.35s ease;
  border: 1px solid rgba(45, 106, 79, 0.06);
}
.product-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: rgba(45, 106, 79, 0.12);
}
.product-image {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  position: relative;
  overflow: hidden;
}
.product-image::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 40px;
  background: linear-gradient(to top, var(--cream), transparent);
}
.product-info {
  padding: 20px;
}
.product-name {
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 16px;
  color: var(--text-dark);
  margin-bottom: 6px;
}
.product-desc {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.product-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.product-price {
  font-family: 'Nunito', sans-serif;
  font-weight: 900;
  font-size: 22px;
  color: var(--green);
}
.product-add-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--green);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: var(--transition);
  border: none;
}
.product-add-btn:hover {
  background: var(--green-dark);
  transform: scale(1.1);
}

/* Carousel navigation */
.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 40px;
}
.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: white;
  border: 2px solid rgba(45, 106, 79, 0.12);
  color: var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: var(--transition);
}
.carousel-btn:hover:not(:disabled) {
  background: var(--green);
  color: white;
  border-color: var(--green);
  transform: scale(1.08);
}
.carousel-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.carousel-dots {
  display: flex;
  gap: 8px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--green-muted);
  border: none;
  transition: var(--transition);
  padding: 0;
}
.carousel-dot.active {
  background: var(--green);
  width: 28px;
  border-radius: 5px;
}

/* ===== SEASONAL PICKS ===== */
.seasonal-section {
  background: linear-gradient(170deg, #fff8e1 0%, var(--cream) 50%, #e8f5e9 100%);
}
.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.seasonal-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all 0.35s ease;
  border: 1px solid rgba(45, 106, 79, 0.06);
  position: relative;
  overflow: hidden;
}
.seasonal-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--orange), var(--orange-dark));
  transform: scaleX(0);
  transition: transform 0.4s ease;
  transform-origin: left;
}
.seasonal-card:hover::before { transform: scaleX(1); }
.seasonal-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.seasonal-emoji {
  font-size: 48px;
  margin-bottom: 16px;
}
.seasonal-name {
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 18px;
  margin-bottom: 8px;
}
.seasonal-desc {
  font-size: 14px;
  color: var(--text-muted);
  margin-bottom: 16px;
  line-height: 1.6;
}
.seasonal-price {
  font-family: 'Nunito', sans-serif;
  font-weight: 900;
  font-size: 20px;
  color: var(--orange-dark);
}
.seasonal-badge {
  position: absolute;
  top: 20px;
  right: 20px;
  background: rgba(244, 162, 97, 0.12);
  color: var(--orange-dark);
  font-weight: 700;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 4px 10px;
  border-radius: 100px;
}

/* ===== CATEGORIES ===== */
.categories-section {
  background: var(--white);
}
.categories-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
}
.category-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 3/4;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.category-card:hover {
  transform: scale(1.05);
}
.category-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  transition: transform 0.4s ease;
}
.category-card:hover .category-bg {
  transform: scale(1.1);
}
.category-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 24px;
  transition: var(--transition);
}
.category-overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(27, 67, 50, 0.85), rgba(27, 67, 50, 0.1) 60%, transparent);
  transition: var(--transition);
}
.category-card:hover .category-overlay::before {
  background: linear-gradient(to top, rgba(27, 67, 50, 0.92), rgba(27, 67, 50, 0.3) 70%, rgba(27, 67, 50, 0.1));
}
.category-name {
  position: relative;
  z-index: 1;
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 18px;
  color: white;
  margin-bottom: 4px;
}
.category-desc {
  position: relative;
  z-index: 1;
  font-size: 13px;
  color: rgba(255,255,255,0.75);
  opacity: 0;
  transform: translateY(10px);
  transition: all 0.35s ease;
  line-height: 1.5;
}
.category-card:hover .category-desc {
  opacity: 1;
  transform: translateY(0);
}

/* ===== BRAND HIGHLIGHTS / STATS ===== */
.stats-section {
  background: var(--green-dark);
  position: relative;
  overflow: hidden;
  padding: 72px 0;
}
.stats-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 50%, var(--green-dark) 100%);
  opacity: 0.9;
}
.stats-pattern {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255,255,255,0.06) 1px, transparent 1px);
  background-size: 24px 24px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  position: relative;
  z-index: 1;
}
.stat-item {
  text-align: center;
}
.stat-number {
  font-family: 'Nunito', sans-serif;
  font-weight: 900;
  font-size: clamp(36px, 5vw, 52px);
  color: white;
  line-height: 1;
  margin-bottom: 8px;
}
.stat-number span {
  color: var(--orange-light);
}
.stat-label {
  font-weight: 600;
  font-size: 16px;
  color: rgba(255,255,255,0.85);
  margin-bottom: 6px;
}
.stat-desc {
  font-size: 13px;
  color: rgba(255,255,255,0.5);
  line-height: 1.5;
}

/* ===== STORE LOCATOR ===== */
.locator-section {
  background: linear-gradient(170deg, #e8f5e9 0%, var(--cream) 100%);
}
.locator-card {
  max-width: 720px;
  margin: 0 auto;
  background: white;
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-lg);
}
.locator-input-row {
  display: flex;
  gap: 12px;
  margin-bottom: 12px;
}
.locator-input {
  flex: 1;
  padding: 16px 20px;
  border: 2px solid rgba(45, 106, 79, 0.12);
  border-radius: var(--radius-md);
  font-size: 16px;
  outline: none;
  transition: var(--transition);
  background: var(--cream);
}
.locator-input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 4px rgba(45, 106, 79, 0.08);
}
.locator-input::placeholder { color: var(--text-muted); }
.locator-search-btn {
  padding: 16px 32px;
  background: var(--green);
  color: white;
  font-weight: 700;
  font-size: 16px;
  border-radius: var(--radius-md);
  border: none;
  transition: var(--transition);
  white-space: nowrap;
}
.locator-search-btn:hover {
  background: var(--green-dark);
  transform: translateY(-1px);
}
.locator-search-btn:active { transform: translateY(0); }

/* Store results */
.store-results {
  display: none;
  margin-top: 24px;
}
.store-results.show { display: block; }
.store-results-title {
  font-family: 'Nunito', sans-serif;
  font-weight: 700;
  font-size: 14px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
.store-item {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 20px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(45, 106, 79, 0.08);
  margin-bottom: 12px;
  transition: var(--transition);
  background: var(--cream);
}
.store-item:hover {
  border-color: var(--green);
  box-shadow: var(--shadow-sm);
}
.store-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: rgba(45, 106, 79, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 22px;
}
.store-details {
  flex: 1;
}
.store-name {
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 16px;
  color: var(--text-dark);
}
.store-address {
  font-size: 14px;
  color: var(--text-muted);
  margin-top: 2px;
}
.store-hours {
  font-size: 13px;
  color: var(--green);
  font-weight: 600;
  margin-top: 4px;
}
.store-distance {
  font-family: 'Nunito', sans-serif;
  font-weight: 900;
  font-size: 18px;
  color: var(--green);
  flex-shrink: 0;
}

/* ===== NEWSLETTER ===== */
.newsletter-section {
  background: var(--white);
}
.newsletter-card {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  background: linear-gradient(135deg, #e8f5e9 0%, #fff8e1 100%);
  border-radius: var(--radius-xl);
  padding: 56px 48px;
  position: relative;
  overflow: hidden;
}
.newsletter-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(45, 106, 79, 0.04) 1px, transparent 1px);
  background-size: 20px 20px;
}
.newsletter-emoji {
  font-size: 56px;
  margin-bottom: 20px;
  position: relative;
}
.newsletter-title {
  position: relative;
  font-size: 32px;
  font-weight: 900;
  margin-bottom: 12px;
}
.newsletter-subtitle {
  position: relative;
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 32px;
  max-width: 440px;
  margin-left: auto;
  margin-right: auto;
}
.newsletter-form {
  position: relative;
  display: flex;
  gap: 12px;
  max-width: 440px;
  margin: 0 auto;
}
.newsletter-input {
  flex: 1;
  padding: 16px 20px;
  border: 2px solid rgba(45, 106, 79, 0.12);
  border-radius: var(--radius-md);
  font-size: 15px;
  outline: none;
  transition: var(--transition);
  background: white;
}
.newsletter-input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 4px rgba(45, 106, 79, 0.08);
}
.newsletter-submit {
  padding: 16px 28px;
  background: var(--orange);
  color: white;
  font-weight: 700;
  font-size: 16px;
  border-radius: var(--radius-md);
  border: none;
  transition: var(--transition);
  white-space: nowrap;
}
.newsletter-submit:hover {
  background: var(--orange-dark);
  transform: translateY(-1px);
}
.newsletter-confirm {
  display: none;
  position: relative;
  margin-top: 20px;
  padding: 14px 20px;
  background: rgba(45, 106, 79, 0.08);
  border-radius: var(--radius-md);
  color: var(--green);
  font-weight: 600;
  font-size: 15px;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.newsletter-confirm.show {
  display: flex;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--green-dark);
  color: rgba(255,255,255,0.7);
  padding: 72px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand {
  max-width: 260px;
}
.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 22px;
  color: white;
  margin-bottom: 14px;
}
.footer-logo-icon {
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,0.15);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}
.footer-tagline {
  font-size: 14px;
  line-height: 1.7;
}
.footer-col-title {
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 15px;
  color: white;
  margin-bottom: 18px;
}
.footer-col a {
  display: block;
  font-size: 14px;
  padding: 5px 0;
  transition: var(--transition);
}
.footer-col a:hover {
  color: white;
  transform: translateX(4px);
}
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
}
.footer-social {
  display: flex;
  gap: 12px;
}
.footer-social-link {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  font-size: 16px;
}
.footer-social-link:hover {
  background: var(--orange);
  transform: translateY(-2px);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-inner {
    flex-direction: column;
    text-align: center;
    padding: 60px 0;
  }
  .hero-content { max-width: 100%; }
  .hero-subtitle { margin-left: auto; margin-right: auto; }
  .hero-ctas { justify-content: center; }
  .hero-image-card { width: 320px; height: 340px; }
  .hero-emoji-grid { font-size: 40px; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .section { padding: 72px 0; }
  .nav-links { display: none; }
  .mobile-menu-btn { display: flex; }
  .hero-inner { gap: 40px; padding: 40px 0; }
  .hero-image-card { width: 280px; height: 300px; }
  .hero-float-tag { display: none; }
  .product-card { width: 220px; }
  .product-image { height: 160px; font-size: 56px; }
  .seasonal-grid { grid-template-columns: 1fr; }
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .stats-section { padding: 56px 0; }
  .locator-card { padding: 32px 24px; }
  .locator-input-row { flex-direction: column; }
  .newsletter-card { padding: 40px 24px; }
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { max-width: 100%; grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .store-item { flex-direction: column; text-align: center; gap: 12px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .section { padding: 56px 0; }
  .hero-image-card { width: 240px; height: 260px; }
  .hero-emoji-grid { font-size: 32px; gap: 14px; }
  .categories-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

